import { readFile } from "node:fs/promises";
import path from "node:path";
import { uploadDir } from "@/lib/uploads";

// Serves the images saved by lib/uploads.ts. Names are generated by the server
// (time + random hex + .webp), so anything else is refused outright.
const safeName = /^[a-z0-9]+-[0-9a-f]{12}\.webp$/;

export async function GET(_request: Request, { params }: RouteContext<"/uploads/[name]">) {
  const { name } = await params;
  if (!safeName.test(name)) return new Response("Not found", { status: 404 });
  try {
    const file = await readFile(path.join(uploadDir, name));
    return new Response(file, {
      headers: {
        "content-type": "image/webp",
        // The name changes with every upload, so the file never does.
        "cache-control": "public, max-age=31536000, immutable",
      },
    });
  } catch {
    return new Response("Not found", { status: 404 });
  }
}
